// HR//0D -- one-click import settings for the real art.
// Assembly: HRZeroDay.Editor  (Editor-only)
// Owner: Dev A. Menu: HR//0D > Import Art Kit
//
// WHY THIS EXISTS: 73 sprites x 6 settings is 438 clicks, and one wrong PPU on one folder is a
// bug nobody spots until the phone. The settings live in art/kit/unity_sprites.json (generated by
// tools/art/make_sprite_manifest.py), so this class only applies them.
using System.Collections.Generic;
using System.IO;
using HRZeroDay.Game;
using UnityEditor;
using UnityEditor.U2D.Sprites;      // SpriteDataProviderFactories -- the only supported way to slice
using UnityEngine;

namespace HRZeroDay.EditorTools
{
    public static class ArtKitImporter
    {
        private const string KitRoot = "Assets/Art/Kit";
        private const string ManifestPath = "Assets/Resources/unity_sprites.json";

        [MenuItem("HR//0D/Import Art Kit", false, 10)]
        public static void ImportAll()
        {
            var manifest = LoadManifest();
            if (manifest == null) return;

            int changed = 0, sliced = 0;
            try
            {
                AssetDatabase.StartAssetEditing();
                for (int i = 0; i < manifest.sprites.Count; i++)
                {
                    var s = manifest.sprites[i];
                    var path = s.assetPath;
                    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
                    if (importer == null) continue;                        // not imported yet
                    if (ApplySettings(importer, s)) changed++;
                    if (s.spriteMode == "Multiple") sliced++;
                }
            }
            finally
            {
                AssetDatabase.StopAssetEditing();
            }

            AssetDatabase.Refresh();
            Debug.Log(string.Format("[HR//0D] art kit import: {0} sprites checked, {1} updated, " +
                                    "{2} sliced strips. Verify with: python tools/art/publish_to_unity.py --verify",
                                    manifest.sprites.Count, changed, sliced));
        }

        private static bool ApplySettings(TextureImporter importer, SpriteEntry s)
        {
            bool dirty = false;

            if (importer.textureType != TextureImporterType.Sprite) { importer.textureType = TextureImporterType.Sprite; dirty = true; }
            if (importer.spritePixelsPerUnit != s.ppu) { importer.spritePixelsPerUnit = s.ppu; dirty = true; }
            if (importer.filterMode != FilterMode.Point) { importer.filterMode = FilterMode.Point; dirty = true; }
            if (importer.textureCompression != TextureImporterCompression.Uncompressed) { importer.textureCompression = TextureImporterCompression.Uncompressed; dirty = true; }
            if (importer.mipmapEnabled) { importer.mipmapEnabled = false; dirty = true; }
            if (!importer.alphaIsTransparency) { importer.alphaIsTransparency = true; dirty = true; }
            if (!importer.wrapMode.Equals(TextureWrapMode.Clamp)) { importer.wrapMode = TextureWrapMode.Clamp; dirty = true; }

            var wantMode = s.spriteMode == "Multiple"
                ? SpriteImportMode.Multiple
                : SpriteImportMode.Single;
            if (importer.spriteImportMode != wantMode) { importer.spriteImportMode = wantMode; dirty = true; }

            // mesh type FullRect (needed for 9-slice), set via the texture settings block
            var settings = new TextureImporterSettings();
            importer.ReadTextureSettings(settings);
            if (settings.spriteMeshType != SpriteMeshType.FullRect)
            {
                settings.spriteMeshType = SpriteMeshType.FullRect;
                importer.SetTextureSettings(settings);
                dirty = true;
            }

            // 9-slice border, UI sheets only
            if (s.kind == "ui")
            {
                var meta = importer.spriteBorder;
                if (meta.x < 8f || meta.y < 8f || meta.z < 8f || meta.w < 8f)
                {
                    importer.spriteBorder = new Vector4(8f, 8f, 8f, 8f);
                    dirty = true;
                }
            }

            // Multi-sprite sheets: name and place each frame explicitly.
            //
            // Unity 6.3 REMOVED TextureImporter.spritesheet (it compiles with a CS0618 warning and then
            // does nothing), so the old code silently produced zero slices -- the scene builder then
            // threw "expected 4 sliced frames" on every applicant. The supported path is the sprite data
            // provider; the import mode has to be set and reimported BEFORE the provider will accept
            // sprite rects, which is why this is done in two steps rather than one.
            if (s.spriteMode == "Multiple")
            {
                if (ApplySpriteRects(s)) dirty = true;
            }

            if (dirty) importer.SaveAndReimport();
            return dirty;
        }

        /// <summary>
        /// Writes the 4 applicant frames through ISpriteEditorDataProvider. Returns true when the asset
        /// changed. Any failure is reported loudly: a silently unsliced sheet is a broken game, not a
        /// cosmetic problem.
        /// </summary>
        private static bool ApplySpriteRects(SpriteEntry s)
        {
            var w = ReadHeaderWidth(s.assetPath);
            var h = ReadHeaderHeight(s.assetPath);
            if (w <= 0 || h <= 0) return false;
            if (w % 4 != 0)
            {
                Debug.LogError("[HR//0D] " + s.assetPath + " is " + w + "px wide -- not divisible by 4, " +
                               "so a 4-frame strip cannot be sliced evenly.");
                return false;
            }

            var cellW = w / 4;
            var baseName = Path.GetFileNameWithoutExtension(s.assetPath).Split(new[] { "_19" }, System.StringSplitOptions.None)[0];
            if (baseName.StartsWith("app_")) baseName = baseName.Substring(4);
            var names = new[] { "neutral", "breathe", "breathe_fidget", "blink" };

            var factories = new SpriteDataProviderFactories();
            factories.Init();
            var provider = factories.GetSpriteEditorDataProviderFromObject(
                AssetImporter.GetAtPath(s.assetPath));
            if (provider == null)
            {
                Debug.LogError("[HR//0D] no sprite data provider for " + s.assetPath +
                               " -- cannot slice. Check that Texture Type is Sprite (2D and UI).");
                return false;
            }
            provider.InitSpriteEditorDataProvider();

            var rects = new SpriteRect[4];
            for (int i = 0; i < 4; i++)
            {
                rects[i] = new SpriteRect
                {
                    name = baseName + "_" + names[i],
                    spriteID = GUID.Generate(),
                    rect = new Rect(i * cellW, 0, cellW, h),   // Unity rect origin is bottom-left
                    alignment = SpriteAlignment.Custom,
                    pivot = new Vector2(0.5f, 0.5f),
                    border = Vector4.zero
                };
            }
            provider.SetSpriteRects(rects);

            var nameFileIdDataProvider = provider.GetDataProvider<ISpriteNameFileIdDataProvider>();
            if (nameFileIdDataProvider != null)
            {
                var pairs = new List<SpriteNameFileIdPair>(4);
                for (int i = 0; i < 4; i++)
                    pairs.Add(new SpriteNameFileIdPair(rects[i].name, rects[i].spriteID));
                nameFileIdDataProvider.SetNameFileIdPairs(pairs);
            }

            provider.Apply();
            return true;
        }

        /// <summary>How many sprite rects the asset actually has right now (0 = unsliced).</summary>
        private static int CountSpriteRects(string assetPath)
        {
            var factories = new SpriteDataProviderFactories();
            factories.Init();
            var provider = factories.GetSpriteEditorDataProviderFromObject(AssetImporter.GetAtPath(assetPath));
            if (provider == null) return 0;
            provider.InitSpriteEditorDataProvider();
            var rects = provider.GetSpriteRects();
            return rects == null ? 0 : rects.Length;
        }

        private static int ReadHeaderWidth(string path)
        {
            var full = Path.Combine(Directory.GetCurrentDirectory(), path);
            if (!File.Exists(full)) return 0;
            using (var fs = new FileStream(full, FileMode.Open, FileAccess.Read))
            {
                var b = new byte[24];
                if (fs.Read(b, 0, 24) < 24) return 0;
                return (b[16] << 24) | (b[17] << 16) | (b[18] << 8) | b[19];
            }
        }

        private static int ReadHeaderHeight(string path)
        {
            var full = Path.Combine(Directory.GetCurrentDirectory(), path);
            if (!File.Exists(full)) return 0;
            using (var fs = new FileStream(full, FileMode.Open, FileAccess.Read))
            {
                var b = new byte[24];
                if (fs.Read(b, 0, 24) < 24) return 0;
                return (b[20] << 24) | (b[21] << 16) | (b[22] << 8) | b[23];
            }
        }

        [MenuItem("HR//0D/Verify Art Import", false, 11)]
        public static void Verify()
        {
            var manifest = LoadManifest();
            if (manifest == null) return;

            var problems = new List<string>();
            for (int i = 0; i < manifest.sprites.Count; i++)
            {
                var s = manifest.sprites[i];
                var importer = AssetImporter.GetAtPath(s.assetPath) as TextureImporter;
                if (importer == null) { problems.Add("not imported: " + s.assetPath); continue; }
                if (importer.filterMode != FilterMode.Point) problems.Add("filter mode: " + s.assetPath);
                if (importer.textureCompression != TextureImporterCompression.Uncompressed) problems.Add("compression: " + s.assetPath);
                if (importer.spritePixelsPerUnit != s.ppu) problems.Add("PPU: " + s.assetPath);
                if (importer.mipmapEnabled) problems.Add("mipmaps on: " + s.assetPath);
                if (s.spriteMode == "Multiple" && CountSpriteRects(s.assetPath) < 4) problems.Add("not sliced: " + s.assetPath);
            }

            if (problems.Count == 0)
                Debug.Log(string.Format("[HR//0D] art import PASS -- {0} sprites are Point, uncompressed, {1} PPU, sliced",
                                        manifest.sprites.Count, 16));
            else
            {
                for (int i = 0; i < problems.Count && i < 20; i++) Debug.LogError("[HR//0D] " + problems[i]);
                Debug.LogError(string.Format("[HR//0D] art import FAIL -- {0} problems. Run HR//0D > Import Art Kit.",
                                             problems.Count));
            }
        }

        private static SpriteManifest LoadManifest()
        {
            var asset = AssetDatabase.LoadAssetAtPath<TextAsset>(ManifestPath);
            if (asset == null)
            {
                Debug.LogError("[HR//0D] " + ManifestPath + " missing. Run: python tools/art/publish_to_unity.py");
                return null;
            }
            return JsonUtility.FromJson<SpriteManifest>(asset.text);
        }
    }
}
